diff --git a/packages/ui/src/app/shell.test.ts b/packages/ui/src/app/shell.test.ts
index 81ebcd3..c705a62 100644
--- a/packages/ui/src/app/shell.test.ts
+++ b/packages/ui/src/app/shell.test.ts
@@ -65,7 +65,7 @@ describe("Shell", () => {
       "/settings",
       "/catalog",
     ]);
-    expect(main[4]?.getAttribute("aria-current")).toBe("page");
+    expect(main[5]?.getAttribute("aria-current")).toBe("page");
     expect(element.querySelector("header sp-kbd")).not.toBeNull();
     expect(element.querySelectorAll("header input[name=theme]")).toHaveLength(3);
     expect(element.querySelectorAll("header input[name=lang]")).toHaveLength(2);
diff --git a/packages/ui/src/dashboard/dashboard-page.test.ts b/packages/ui/src/dashboard/dashboard-page.test.ts
index 4ac64bb..fdec86e 100644
--- a/packages/ui/src/dashboard/dashboard-page.test.ts
+++ b/packages/ui/src/dashboard/dashboard-page.test.ts
@@ -35,7 +35,7 @@ function viewFor(params: StatsParams): StatsView {
       ? params.period
       : "30d";
   const [kind, name] = (params.who ?? "").split(":");
-  const who =
+  const who: StatsQuery["who"] =
     (kind === "person" || kind === "agent" || kind === "model") && name !== undefined
       ? { kind, name }
       : undefined;

evidence.text:
/** One person, agent or model; an empty name is «(sin dato)»: the changes that do not say. */
export interface StatsWho {
  readonly kind: StatsWhoKind;
  readonly name: string;
}

/** What the panel looks at: a period, and maybe one person, agent or model, and one lane. */
export interface StatsQuery {
  readonly period: StatsPeriod;
  readonly who?: StatsWho;
  readonly kind?: ChangeKind;
}

